// De oid komt uit het antwoord van Microsoft, niet uit het verzoek: wat een
// browser over zichzelf beweert mag een server niet geloven.
//
// Zonder sessieId vraagt de pagina haar lijst op, met sessieId de inhoud van
// een gesprek. Beide filteren op die oid, dus het raden van andermans
// sessie-id levert nul rijen op.
const wie = $input.first().json;
const verzoek = $('Verzoek binnen').first().json;
const sessieId = verzoek.body?.sessieId ?? verzoek.sessieId ?? '';

if (!wie.id) { throw new Error('geen identiteit uit het token'); }

const oid = encodeURIComponent(wie.id);
const basis = 'https://buddy.driessengroep.nl/data/';

if (!sessieId) {
  return [{ json: { soort: 'lijst', url: basis + 'gesprekken'
    + '?entra_oid=eq.' + oid
    + '&select=sessie_id,titel,bijgewerkt'
    + '&order=bijgewerkt.desc&limit=200' } }];
}

return [{ json: { soort: 'gesprek', url: basis + 'beurten'
  + '?sessie_id=eq.' + encodeURIComponent(sessieId)
  + '&entra_oid=eq.' + oid
  + '&select=beurt_id,vraag,modus,advies,forum,klaar_op'
  + '&order=klaar_op.asc' } }];

// Hoe n8n een lijst teruggeeft verschilt per versie: soms een item per rij,
// soms een item met de hele lijst erin. Daarom vangen we beide vormen op.
// Staat er niets, dan levert Always Output Data een leeg item - dat hoort
// een lege lijst te worden en geen rij vol undefined.
const items = $input.all().map((i) => i.json);
const eerste = items[0];
const rijen = Array.isArray(eerste)
  ? eerste
  : items.filter((r) => r && Object.keys(r).length);

const soort = $('Wat wordt gevraagd').first().json.soort;

if (soort === 'lijst') {
  return [{ json: { gesprekken: rijen.map((r) => ({
    sessieId: r.sessie_id,
    titel: r.titel ?? '',
    bijgewerkt: r.bijgewerkt ?? null,
  })) } }];
}

return [{ json: { beurten: rijen.map((r) => ({
  vraag: r.vraag ?? '',
  advies: r.advies ?? '',
  forum: r.forum ?? [],
  modus: r.modus ?? '',
  klaarOp: r.klaar_op ?? null,
})) } }];
